const body = $json.body || {};
const handle = String(body.handle || "valentinloiseau.ai").replace(/^@/, "").trim();
const followers = Number(body.followers || 1400000);
const rate = Math.max(250, Math.round(followers / 1000) * 12);
const today = new Date();
const dateLabel = today.toISOString().slice(0, 10);
const dueLabel = new Date(today.getTime() + 14 * 86400000).toISOString().slice(0, 10);
function safe(s) {
  var t = String(s);
  var out = "";
  for (var i = 0; i < t.length; i++) {
    var c = t.charCodeAt(i);
    if (c >= 32 && c <= 126 && c !== 40 && c !== 41 && c !== 92) { out += t.charAt(i); }
  }
  return out;
}
const L = [];
L.push("CREATOR PARTNERSHIP AGREEMENT");
L.push("");
L.push("Between: ElevenLabs Inc. - the Brand");
L.push("And: @" + handle + " - the Creator");
L.push("Agreement date: " + dateLabel);
L.push("");
L.push("1. CAMPAIGN");
L.push("Campaign: #seedance");
L.push("Audience size at signature: " + followers.toLocaleString("en-US") + " followers");
L.push("");
L.push("2. DELIVERABLES");
L.push("Two TikTok videos, 15-45 seconds each");
L.push("One story frame with link sticker");
L.push("First draft due: " + dueLabel);
L.push("");
L.push("3. PAYOUT");
L.push("Fee: USD " + rate.toLocaleString("en-US"));
L.push("Terms: net 30 from the date content is verified live");
L.push("Method: bank transfer to the account on file");
L.push("");
L.push("4. USAGE RIGHTS");
L.push("Paid social usage for 90 days from first post");
L.push("Organic usage on Brand channels in perpetuity");
L.push("");
L.push("5. EXCLUSIVITY");
L.push("No competing AI audio brand for 30 days from first post");
L.push("");
L.push("6. DISCLOSURE");
L.push("Creator will label posts as a paid partnership and include #ad");
L.push("");
L.push("");
L.push("Signed for the Brand                 Signed by the Creator");
L.push("");
L.push("_______________________              _______________________");
L.push("ElevenLabs Inc.                      @" + handle);
L.push("");
L.push("Document generated automatically. Mock terms for demonstration.");
let content = "BT\n/F1 11 Tf\n56 786 Td\n15 TL\n";
L.forEach(function (l) { content += "(" + safe(l) + ") Tj T*\n"; });
content += "ET";
const objs = {};
objs[1] = "<< /Type /Catalog /Pages 2 0 R >>";
objs[2] = "<< /Type /Pages /Kids [3 0 R] /Count 1 >>";
objs[3] = "<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>";
objs[4] = "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>";
objs[5] = "<< /Length " + content.length + " >>\nstream\n" + content + "\nendstream";
let pdf = "%PDF-1.4\n";
const offsets = {};
for (let i = 1; i <= 5; i++) {
  offsets[i] = pdf.length;
  pdf += i + " 0 obj\n" + objs[i] + "\nendobj\n";
}
const xrefPos = pdf.length;
pdf += "xref\n0 6\n0000000000 65535 f \n";
for (let i = 1; i <= 5; i++) {
  let o = String(offsets[i]);
  while (o.length < 10) { o = "0" + o; }
  pdf += o + " 00000 n \n";
}
pdf += "trailer\n<< /Size 6 /Root 1 0 R >>\nstartxref\n" + xrefPos + "\n%%EOF";
const b64 = Buffer.from(pdf, "latin1").toString("base64");
const fileName = "elevenlabs-contract-" + handle + ".pdf";
let text = "";
L.forEach(function (l, i) { text += (i ? "\n" : "") + l; });
const meta = [];
meta.push({ k: "Creator", v: "@" + handle });
meta.push({ k: "Fee", v: "USD " + rate.toLocaleString("en-US") });
meta.push({ k: "Draft due", v: dueLabel });
meta.push({ k: "File", v: fileName });
const out = { ok: true, action: "contract", headline: "Contract generated for @" + handle, detail: "Names, dates and payout rates merged into the template, rendered to PDF and delivered. Ready to route for e-signature.", meta: meta, body: text, fileName: fileName };
return [{ json: out, binary: { data: { data: b64, mimeType: "application/pdf", fileName: fileName, fileExtension: "pdf" } } }];

